/** Peng, Wickham & Alivisatos (1998), DOI 10.1021/ja9805425.
 * Functional source-scoped diagrams. Apparatus geometry and liquid colors are illustrative.
 * No model-generated spectra, measured lattice or unreported injection hardware is implied.
 */
const DOI='10.1021/ja9805425';
const C={ink:'#254a5c',line:'#7c9aac',pale:'#edf5f9',liquid:'#b7d6dc',green:'#468e91',hot:'#bc8057',gold:'#d8b66c'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const txt=(x,y,s,size=18)=>`<text x="${x}" y="${y}" text-anchor="middle" font-family="Arial,sans-serif" font-size="${size}">${esc(s)}</text>`;
const line=(d,col=C.line,w=2)=>`<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const box=(x,y,w,h,fill=C.pale)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="9" stroke="${C.line}" stroke-width="2" fill="${fill}"/>`;
const arrow=(x,y,a=0)=>`<g transform="translate(${x} ${y}) rotate(${a})">${line('M-21 0H15',C.green,2.4)}<path d="M10 -6L20 0L10 6Z" fill="${C.green}"/></g>`;
function wrap(s,n){const out=[];let row='';for(const w of String(s).split(/\s+/)){if((row+' '+w).trim().length>n&&row){out.push(row);row=w;}else row=(row+' '+w).trim();}if(row)out.push(row);return out;}
const title=s=>wrap(s,43).map((s,i)=>txt(300,31+i*25,s,21)).join('');
const note=s=>wrap(s,77).map((s,i)=>txt(300,361+i*18,s,14)).join('');
const rtype=r=>r.record_id.replace('peng-1998-','');
const op=(r,id)=>r.operations.find(o=>o.id===id)||{};
const massRatio=r=>(r.stocks.find(s=>s.components?.every(c=>c.quantities?.mass_parts))?.components||[]).map(c=>c.quantities.mass_parts.value).join(' : ');
const isInAs=r=>rtype(r).startsWith('inas');
function q(o,key){const v=o.parameters?.[key];if(!v||v.status==='not_reported')return null;const unit={degC:'°C',min:'min',mL:'mL',g:'g',s:'s',g_per_mL:'g/mL'}[v.unit]||v.unit||'';return v.value!=null?`${/strictly less/.test(v.qualifier||'')?'<':''}${v.approximate?'≈':''}${v.value}${unit==='dimensionless'?'':' '+unit}`:v.minimum!=null&&v.maximum!=null?`${v.minimum}–${v.maximum} ${unit}`:v.maximum!=null?`${v.maximum_exclusive||v.maximum_inclusive===false?'<':'≤'}${v.maximum} ${unit}`:v.qualifier||null;}
function conditions(o,keys,x=468,y=163){return keys.map(([k,label])=>{const v=q(o,k);return v?label+': '+v:null;}).filter(Boolean).map((s,i)=>txt(x,y+i*34,s,17)).join('');}
function vial(x,y,{precipitate=false}={}){return `<g transform="translate(${x} ${y})">${line('M-36 -55V46Q0 59 36 46V-55M-36 -55H36',C.line,2.4)}<path d="M-33 -1H33V45Q0 57 -33 45Z" fill="${C.liquid}" opacity=".65"/>${precipitate?'<path d="M-28 39Q0 29 28 39V43Q0 52 -28 43Z" fill="#829cb0"/>':''}</g>`;}
function flask(x,y,{stir=false}={}){return `<g transform="translate(${x} ${y})"><path d="M-17 -84H17V-37C69 -12 84 55 40 77Q0 92 -40 77C-84 55 -69 -12 -17 -37Z" fill="${C.pale}" stroke="${C.line}" stroke-width="2.5"/><path d="M-59 21H59C66 50 38 82 0 84C-38 82 -66 50 -59 21Z" fill="${C.liquid}" opacity=".75"/>${stir?line('M-14 62H14',C.ink,5):''}</g>`;}
function heater(x,y){return box(x-91,y,182,18,'#e3e9ed')+[x-28,x,x+28].map(a=>line(`M${a} ${y-7}q-6 -9 0 -18t0 -18`,C.hot,2.2)).join('');}
function stock(o,r){const inas=isInAs(r);return title(inas?'Prepare the InAs precursor injection feed':'Prepare the CdSe precursor injection stock')+box(24,92,260,204)+txt(154,129,inas?'TMS₃As':'Se',24)+txt(154,171,inas?'InCl₃ source':'Cd(CH₃)₂',24)+txt(154,213,inas?'TOP solvent':'Tributylphosphine',20)+txt(154,266,'Mass ratio · '+massRatio(r),18)+arrow(322,198)+vial(433,202)+txt(434,294,inas?'Cold injection feed':'Cold stock solution',19)+note(inas?'Components are not a solved molecular complex. Feed-preparation details and absolute component masses are unreported.':'Se is the source-named stock component; no elemental-Se-only injection or measured phosphine–Se speciation is asserted.');}
function heat(o,r){const upstream=rtype(r)==='incl3-top-stock',inas=isInAs(r);return title(upstream?'Prepare the concentrated InCl₃–TOP solution':inas?'Heat the TOP growth medium':'Heat TOPO under flowing argon')+flask(230,202)+heater(230,292)+(upstream||!inas?line('M100 119H210V151',C.green,2.5)+arrow(210,142,90)+txt(105,104,upstream?'Ar':'Flowing Ar',18):'')+txt(457,128,upstream?'InCl₃ in distilled TOP':inas?'TOP growth medium':'TOPO growth medium',17)+conditions(o,[['temperature','Solution'],['topo_mass','TOPO'],['top_mass','TOP'],['incl3_per_top_volume','InCl₃ / TOP']],462,174)+note(upstream?'The heated solution is subsequently cooled and stored in a drybox; no fixed In–TOP coordination is inferred.':inas?'The source does not independently specify growth-stage gas flow or pressure. Heater geometry is illustrative.':'Four grams of TOPO is the host charge. Bath medium, gas-flow rate and pressure are not specified.');}
function injection(o,r){const inas=isInAs(r);return title(inas?'Rapidly inject the cold InAs precursor feed':'Rapidly inject the cold CdSe precursor stock')+box(39,99,267,81)+txt(171,131,inas?'TMS₃As / InCl₃ / TOP':'Se / CdMe₂ / TBP stock',18)+txt(171,159,'Cold feed · '+q(o,'injection_volume')+' · '+q(o,'injection_duration_upper_bound'),17)+line('M307 141H382V166',C.green,3)+arrow(382,174,90)+flask(382,256,{stir:!inas})+txt(141,240,inas?'TOP host':'Rapidly stirred TOPO',18)+txt(140,272,'Initially '+q(op(r,'heat'),'temperature'),18)+txt(140,303,'After '+q(o,inas?'initial_post_injection_temperature':'post_injection_temperature'),18)+note('The injection connector is schematic; a particular syringe, pump, needle or vessel geometry is not specified.');}
function grow(o,r){const inas=isInAs(r),cont=o.id==='continue';return title(cont?'Continue InAs growth after the first refeed':inas?'Grow InAs nanocrystals at the reported temperature':'Grow CdSe and follow the size-distribution evolution')+flask(233,208)+heater(233,299)+txt(460,125,inas?'InAs growth':'CdSe growth',23)+conditions(o,[['temperature','Solution'],['growth_temperature','Nominal'],['elapsed_time_before_reinjection','Elapsed'],['elapsed_time_to_next_injection','Next feed'],['next_injection_elapsed_time','Next feed']],462,168)+(inas&&o.id==='grow'?txt(462,230,'Growth: '+q(op(r,'recover'),'temperature'),17):'')+txt(459,270,'Aliquot branch → analysis',16)+note(inas?'Aliquot measurements are a separate procedure. No theoretical growth curve is presented as measured size data.':'The nominal growth temperature is inferred from the post-injection value; an independently maintained hold is not stated.');}
function recover(o,r){return title('Bring the InAs mixture to its growth temperature')+flask(239,215)+heater(239,302)+txt(460,134,'After injection',20)+txt(460,182,q(op(r,'injection'),'initial_post_injection_temperature')+' initially',21)+arrow(460,218,90)+txt(460,272,q(o,'temperature')+' growth',21)+note('The initial injection-induced cooling and subsequent 260 °C growth are distinct source conditions; ramp rate is unreported.');}
function refeed(o,r){const inas=isInAs(r);return title(inas?'Add the next InAs precursor feed':'Slowly add CdSe stock to refocus the distribution')+vial(117,151)+txt(117,253,'Additional stock',18)+arrow(207,175)+line('M240 174H356V184',C.green,2.5)+arrow(356,191,90)+flask(356,264)+txt(457,94,inas?'Additional injection':'Slow injection',18)+conditions(o,[['injection_volume','Feed'],['elapsed_time_from_first_injection','Elapsed']],458,130)+note(inas?'The source reports additional feed volumes and times, but not the rate or duration of either re-injection.':'The 190 min label is elapsed time after the first injection, not the slow-injection duration.');}
function cool(){return title('Cool the prepared InCl₃–TOP stock')+vial(269,206)+arrow(415,156,90)+txt(467,233,'Cooling',22)+txt(468,272,'Endpoint unreported',16)+note('No final stock temperature, cooling rate, ice bath or cooling duration is specified.');}
function store(){return title('Move the cooled InCl₃–TOP stock into a drybox')+box(78,93,444,224,'#f5fafc')+txt(300,126,'Drybox storage',22)+vial(300,211)+txt(300,294,'Cooled InCl₃ in TOP',18)+note('Storage temperature and duration are unreported. The source does not specify the drybox gas.');}
function withdraw(o,r){const inas=isInAs(r);return title(inas?'Withdraw InAs aliquots at selected growth times':'Withdraw CdSe aliquots at selected growth times')+flask(162,210)+arrow(290,170)+vial(426,218)+txt(427,311,(q(o,'aliquot_volume')||'Unreported volume')+' aliquot',18)+txt(163,322,'Growth mixture',18)+note('Sampling occurs at various time intervals. The diagram specifies no transfer instrument or unreported quench.');}
function precipitate(o,r){return title('Precipitate the withdrawn CdSe aliquot in methanol')+vial(112,188)+txt(112,286,q(op(r,'withdraw'),'aliquot_volume')+' aliquot',18)+arrow(203,191)+box(238,138,130,110)+txt(303,180,'Methanol',19)+txt(303,214,q(o,'methanol_volume'),22)+arrow(414,191)+vial(508,190,{precipitate:true})+txt(508,286,'CdSe precipitate',17)+note('This precipitation belongs to the withdrawn CdSe aliquot. It is not a whole-batch recipe or an InAs workup.');}
function purify(){return title('Purify the CdSe aliquot before yield measurement')+vial(115,190,{precipitate:true})+arrow(205,189)+box(240,124,280,141)+txt(380,161,'Remove excess TOPO',19)+txt(380,201,'byproducts and solvent',19)+txt(380,239,'Recovery details unreported',16)+txt(304,317,'Measure mass and particle yield after purification',17)+note('No centrifuge speed, wash count, drying operation, isolation device or final powder state is supplied.');}
function disperse(o,r){const inas=isInAs(r);return title(inas?'Dilute the InAs aliquot in toluene':'Redissolve the purified CdSe aliquot in toluene')+vial(111,184,{precipitate:!inas})+txt(110,285,inas?'InAs aliquot':'Purified CdSe',18)+arrow(201,189)+box(238,137,130,105)+txt(303,177,'Toluene',21)+txt(303,213,inas?'Dilution':'Redissolution',16)+arrow(414,189)+vial(509,184)+txt(509,285,'Optical sample',17)+note(inas?'The InAs method does not state methanol precipitation, purification or a target optical density.':'Toluene volume is not supplied; particle concentration follows the source optical-density target in the next stage.');}
function adjust(o){return title('Adjust the CdSe optical sample for PL measurement')+vial(202,201)+box(332,125,223,131)+txt(444,164,'Optical density',21)+txt(444,204,q(o,'optical_density')+' ± '+q(o,'optical_density_tolerance'),26)+txt(444,236,'PL samples',17)+txt(200,300,'CdSe in toluene',19)+note('The excitation wavelength, cuvette path length and added toluene volume are unreported; none is inferred from OD.');}
function optical(o,r){const inas=isInAs(r);return title(inas?'Record InAs absorption and photoluminescence':'Record CdSe absorption and photoluminescence')+box(27,145,141,78)+txt(98,177,'Optical',18)+txt(98,205,'excitation',18)+arrow(207,185)+box(265,130,72,115,'#f8fcfe')+`<rect x="270" y="170" width="62" height="70" fill="${C.liquid}"/>`+txt(300,279,inas?'InAs / toluene':'CdSe / toluene',18)+arrow(389,185)+box(432,144,143,79)+txt(503,177,'Optical',18)+txt(503,205,'detection',18)+txt(300,322,inas?'Original SI spectra':'Original main Figure 1',17)+note('Functional optical workflow only: detector geometry, cuvette dimensions and instrument settings are not specified.');}
function calibrate(){return title('Use the source PL-energy-to-size calibration')+box(35,128,214,138)+txt(142,165,'CdSe calibration',20)+txt(142,207,'Keep material identity',16)+txt(142,242,'SI Supplemental page 1',15)+txt(299,198,'OR',19)+box(352,128,214,138)+txt(459,165,'InAs calibration',20)+txt(459,207,'Previously TEM-calibrated',15)+txt(459,242,'SI Supplemental page 3',15)+note('Calibration tables are not newly measured specimens from the kinetic synthesis series. No new TEM size is inferred.');}
function convert(){return title('Translate PL into an estimated size distribution')+box(36,129,200,135)+txt(136,168,'Measured PL',20)+txt(136,213,'CdSe or InAs',18)+arrow(285,193)+box(331,129,234,135)+txt(448,166,'Material calibration',19)+txt(448,205,'δ emission per size',17)+txt(448,238,'Equal emission efficiency',15)+note('These author assumptions broaden the estimated distributions. For InAs, only the high-energy half avoids reabsorption.');}
function moments(){return title('Report the first and second distribution moments')+box(37,126,220,145)+txt(147,163,'Estimated size distribution',15)+txt(147,206,'PL-derived',20)+txt(147,243,'Not direct microscopy',16)+arrow(300,196)+box(345,126,220,145)+txt(455,162,'Mean size',22)+txt(455,205,'Variance / standard deviation',14)+txt(455,244,'No third moment',17)+note('The paper reports no resolved distribution asymmetry. Calibration assumptions and specimen scope remain attached.');}
const routes={
 'cdse-focusing':{'prepare-stock':stock,heat,injection,grow,refeed},
 'inas-focusing':{'prepare-feed':stock,heat,injection,recover,grow,refeed1:refeed,continue:grow,refeed2:refeed},
 'incl3-top-stock':{heat,cool,store},
 'cdse-aliquot-analysis':{withdraw,precipitate,purify,redissolve:disperse,'adjust-od':adjust,measure:optical},
 'inas-aliquot-analysis':{withdraw,dilute:disperse,measure:optical},
 'pl-size-analysis':{calibrate,convert,moments}
};
export function buildPeng1998Scene(o,r){if(!r?.sources?.some(s=>s.doi===DOI)||!/^peng-1998-/.test(r.record_id))return null;const h=routes[rtype(r)]?.[o?.id];if(!h)return null;return {kind:o.action,svg:`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 412" role="img" aria-label="${esc(o.label)} — explanatory process diagram" style="width:100%;height:auto;font-family:Arial,sans-serif;fill:${C.ink}"><title>${esc(o.label)}</title><desc>Source-scoped functional stock, thermal, feed, aliquot and measurement workflow. Vessel shapes, colors and flow arrows are illustrative. No measured molecular complex, lattice, spectrum or unreported apparatus is generated.</desc>${h(o,r)}</svg>`,caption:'Source-specific explanatory diagram. The selected canonical operation supplies the conditions and quantities. Vessel shapes, colors and flow arrows are illustrative; no atomistic solution speciation, measured geometry or synthetic optical spectrum is claimed.'};}
export function createPeng1998Art(o,r){const s=buildPeng1998Scene(o,r);if(!s)return null;const n=document.createElement('div');n.className='protocol-art protocol-art-peng1998';n.dataset.scene='peng1998-'+s.kind;n.style.height='auto';n.innerHTML=s.svg;return n;}
